import { Directive, Input, HostListener, ElementRef } from '@angular/core';

@Directive({
    standalone: true,
    selector: '[appInputMask]'
})
export class InputMaskDirective {

    @Input('appInputMask') mask: string = '';

    constructor(private el: ElementRef<HTMLInputElement>) { }
    @HostListener('input', ['$event'])
    onInput(event: Event): void {
        const input = this.el.nativeElement;
        const value = input.value.toUpperCase(); // Handle input as uppercase
        let formattedValue = '';
        let maskIdx = 0;
        let valueIdx = 0;

        while (maskIdx < this.mask.length && valueIdx < value.length) {
            const maskChar = this.mask[maskIdx];
            const valueChar = value[valueIdx];

            if (maskChar === '0' && /\d/.test(valueChar)) {
                formattedValue += valueChar;
                maskIdx++;
                valueIdx++;
            } else if (maskChar === 'A') {
                // Check if the next three characters form a valid month
                const potentialMonth = value.substring(valueIdx, valueIdx + 3);
                if (this.isMonth(potentialMonth)) {
                    formattedValue += potentialMonth;
                    maskIdx += 3; // Skip ahead in the mask for the next parts
                    valueIdx += 3; // Move the input index ahead by three
                } else {
                    break; // Stop processing if a valid month isn't found
                }
            } else if (maskChar === ' ' || maskChar === '-') {
                formattedValue += maskChar;
                maskIdx++;
                if (valueChar === maskChar) {
                    valueIdx++; // Only advance input index if it matches the mask
                }
            } else {
                // Skip mask characters that aren't placeholders
                maskIdx++;
            }
        }

        if (this.mask == '') {
            formattedValue = input.value;
        }

        input.value = formattedValue;
        event.preventDefault(); // Optional: Prevent the default to handle input manually
    }

    private isMonth(value: string): boolean {
        const months = ['J', 'JA', 'JAN', 'F', 'FE', 'FEB', 'M', 'MA', 'MAR', 'A', 'AP', 'APR', 'MAY', 'JU', 'JUN', 'JUL', 'AU', 'AUG', 'S', 'SE', 'SEP', 'O', 'OC', 'OCT', 'N', 'NO', 'NOV', 'D', 'DE', 'DEC'];
        return months.includes(value);
    }
}

