import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, Output, SimpleChanges, ViewChild, inject, input } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatMenuModule } from '@angular/material/menu';
import { MatRadioModule } from '@angular/material/radio';
import { IconComponent } from '../icon/icon.component';
import { ButtonComponent } from '../button/button.component';
import { CommunicationService } from '../../services/communication/communication.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { InputMaskDirective } from '../../directive/input-mask.directive';
import { FilecolumnService } from '../../services/filecolumn/filecolumn.service';
import { MatSelectModule } from '@angular/material/select';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { advanceFiler, searchedSummary } from '../../../userpanel/interfaces/advance-search.interface';
import { AnnotFilterComponent } from '../../../userpanel/components/annot-filter/annot-filter.component';
import { HeaderService } from '../../../core/services/header/header.service';
import { AdvanceSearchService } from '../../../userpanel/services/advance-search/advance-search.service';
import { ActivatedRoute, Router } from '@angular/router';
import { Title } from '@angular/platform-browser';
import { BroadcastingService } from '../../../core/services/broadcasting/broadcasting.service';
import { broadCastBody } from '../../../core/interfaces/login.interface';
import { Subscription } from 'rxjs';
import { Location } from '@angular/common';
import { BROADCAST_EVENTS } from '../../../userpanel/utility/user-panel-constants';

@Component({
  selector: 'search',
  standalone: true,
  imports: [CommonModule, MatMenuModule, MatRadioModule, FormsModule, IconComponent, ButtonComponent, InputMaskDirective,
    MatSelectModule, MatCheckboxModule, AnnotFilterComponent
  ],
  templateUrl: './search.component.html',
  styleUrl: './search.component.scss'
})
export class SearchComponent {
  private titleS = inject(Title);
  @Input() isAdmin: boolean
  mask: string = "";
  issearched: boolean = false;
  @Input() isPresent: boolean = false
  @Input() isadvanced: boolean = false
  @Output() onSearch: EventEmitter<advanceFiler> = new EventEmitter<advanceFiler>();
  @Output() OnClear: EventEmitter<any> = new EventEmitter<any>();
  @ViewChild('myInput') myInputElementRef: ElementRef;
  mainsearch: boolean = false;
  reqcols: any = [];
  dateType: string = 'A'
  isElasticsearch = false;
  checkalltype: boolean = true;
  @Input() jFilter: advanceFiler = { cWithin: this.cf.searchin, cMatchCase: 'C', cSearch: '', cLocation: 'A' } as advanceFiler;
  @Output() jFilterChange = new EventEmitter<advanceFiler>();
  elasticSummary: searchedSummary = { totalBDIDs: 0 } as searchedSummary;
  showfilter: boolean = true;
  @Input() nBundleid: string;
  @Input() currentfolder: { cBundlename: string, nBundleid: string } = { cBundlename: 'Master Bundle', nBundleid: null };
  isAlltypes: boolean = false;
  window_content: any;
  window_metadata: any;
  broadCastSubscription: Subscription;
  searchInputClearSubscription: Subscription;
  constructor(private cs: CommunicationService, public cf: CommonfunctionService,
    private fcs: FilecolumnService, private cdr: ChangeDetectorRef, public headSearvice: HeaderService,
    private advanceSearchService: AdvanceSearchService, private router: Router, private broadCastService: BroadcastingService,
    private location: Location) {
  }




  ngOnInit(): void {
    this.jFilter;
    this.broadCastSubscription = this.broadCastService.onSearchChange().subscribe((body: broadCastBody) => {
      if (body.event == BROADCAST_EVENTS.SEARCH_CHANGED) {
        if (body.data.jFilter?.cWithin == this.headSearvice?.search_within && body.data.nCaseid == (this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid)) {
          this.headSearvice.isGlobalSearch = true;
          this.headSearvice.jFilter = body.data.jFilter;
          this.titleS.setTitle(this.headSearvice.search_within == 'I' ? 'Content Search' : 'Metadata Search');

          this.issearched = true;
          this.jFilter = body.data.jFilter;
          this.cf.jFTypes = this.jFilter.jFTypes;

          if (this.cf.jFTypes.length > 0) {
            this.cf.searchFilter[4].list.map(e => {
              e.select = e.types.some(type => this.jFilter.jFTypes.includes(type));
            })
            this.checkalltype = false
          } else {
            this.cf.searchFilter[4].list.map(e => e.select = false)
            this.checkalltype = true
          }
          this.currentfolder.nBundleid = this.jFilter?.nBundleid;
          this.currentfolder.cBundlename = this.jFilter?.cBundlename || 'Master Bundle';
          this.checkFilter();
          this.mainsearch = true;
          this.searchChange()
          this.cdr.detectChanges();

        }
      }
    })
    this.broadCastService.onSearchDeactivate().subscribe((body: broadCastBody) => {
      if (body.event == BROADCAST_EVENTS.DEACTIVATE_SEARCH && !this.headSearvice.isGlobalSearch) {
        if (body.data.cWithin == 'I' && body.data.nCaseid == (this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid)) {
          this.window_content = null
        } else {
          this.window_metadata = null
        }
      }
    });

    if (this.headSearvice.isGlobalSearch) {
      this.cf.jFTypes = this.jFilter.jFTypes;
      if (this.cf.jFTypes.length > 0) {
        this.cf.searchFilter[4].list.map(e => {
          e.select = e.types.some(type => this.jFilter.jFTypes.includes(type));
        })
        this.checkalltype = false
      } else {
        this.checkalltype = true
      }
      this.currentfolder.nBundleid = this.jFilter?.nBundleid || null;
      this.currentfolder.cBundlename = this.jFilter?.cBundlename || 'Master Bundle';

    }
    // if (this.isadvanced) {
    //   let val = { "cKey": "Inside Files", nValue: "I", select: false };
    //   this.cf.searchFilter[2].list.push(val);
    // }
    this.reqcols = this.fcs.tablecols;
    let ind = this.reqcols.findIndex(e => e.name == 'Tab' && e.isshow)
    // if (ind > -1) {
    //   this.cf.contentType = this.reqcols[ind].sortKey
    // } else if (this.reqcols.find(e => e.name == 'Name' && e.isshow)) {
    //   ind = this.reqcols.findIndex(e => e.name == 'Name' && e.isshow)
    //   this.cf.contentType = this.reqcols[ind].sortKey
    // } else {
    //   let val = this.reqcols.filter(e => e.isshow)[0]
    //   this.cf.contentType = val.sortKey
    // }
    this.checkFilter()

    if (this.issearched) {
      this.mainsearch = true;
      this.searchChange()
    }

    this.searchInputClearSubscription = this.cs.functionCalled$.subscribe(async (e) => {
      if (e.event == 'CLEAR_SEARCH_INPUT') {
        this.jFilter.cSearch = '';
        this.jFilterChange.emit(this.jFilter);
      }
      if (e.event == 'CLEAR_SEARCH_ALL') {
        // this.jFilter.cSearch = '';
        // this.jFilterChange.emit(this.jFilter);
        this.clearsearch()
      } else if (e.event == 'UPDATE-SEARCH-URL') {
        this.updateUrlWithNewFilter(e.jFilter)
      }
      // if (e.event == 'SEARCH_FILES_EXISTING_FILTER') {
      //  
      //   this.currentfolder = this.headSearvice.currentfolder
      //   this.jFilter.nBundleid = this.currentfolder?.nBundleid || 0;
      //   this.jFilter.cBundlename = this.currentfolder?.cBundlename || 'Master Bundle';
      // }
    })
    this.cdr.detectChanges()
  }

  searchChange() {
    if (!this.jFilter) {
      this.jFilter = { cMatchCase: 'E', cSearch: '', cWithin: this.cf.searchin, cLocation: 'A', contentType: 'All' } as advanceFiler
      this.jFilterChange.emit(this.jFilter);
    }
    this.jFilter.jFTypes = this.cf.jFTypes;
    this.jFilter.cWithin = this.cf.searchin
    // this.jFilter.nBundleid = this.jFilter?.nBundleid || this.currentfolder.nBundleid;
    if (!this.headSearvice.isGlobalSearch) {

      this.jFilter.isGlobalSearch = true;
      this.jFilter.nOBundleid = this.jFilter.nBundleid;
      this.jFilter.nSectionid = this.headSearvice.nSectionid;
      this.jFilter.nOSectionid = this.headSearvice.nSectionid;

      const wind = this.jFilter.cWithin == 'I' ? this.window_content : this.window_metadata;
      if(this.jFilter.cLocation =='A'){
        this.jFilter.nBundleid = null
      }

      if (wind && !wind.closed) {
        this.broadCastService.portMessage({
          event: 'SEARCH-CHANGED', data: { jFilter: this.jFilter, nCaseid: this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid }
        })
        wind.focus();
      } else {
        const url = this.router.serializeUrl(
          this.router.createUrlTree([(location.href.includes('managefiles/bundlemanagement/') ? '/managefiles/bundlemanagement' : '/myfiles/filesaction'), btoa(JSON.stringify({ id: this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid, jFilter: this.jFilter }))])
        );
        const openedWindow = window.open(`${location.origin}${url}`, '_blank')
        this.jFilter.cWithin == 'I' ? this.window_content = openedWindow : this.window_metadata = openedWindow;
      }

      // window.open(url, '_blank');
    } else {
      this.jFilter.nBundleid = this.jFilter?.nBundleid || this.currentfolder?.nBundleid || null;
      this.jFilter.cBundlename = this.jFilter.cLocation == 'T' ? this.jFilter.cBundlename || this.currentfolder?.cBundlename || 'Master Bundle' : 'Master Bundle';
      this.nBundleid = this.currentfolder?.nBundleid || this.jFilter?.nBundleid || null;
      this.isElasticsearch = false;
      this.myInputElementRef?.nativeElement?.blur();
      this.issearched = true;
      this.showfilter = false;
      this.jFilter.nBundleid = this.jFilter?.nOBundleid;
      if (this.cf.searchin == 'I') {
        this.emitSearch();
        this.isElasticsearch = true;
      } else {
        this.cs.callFunction({ event: 'FETCH-META-BUNDLES', jFilter: this.jFilter });
        this.cs.callFunction({ event: 'SEARCH_FILES', jFilter: this.jFilter, type: this.cf.searchin == 'I' ? 'E' : 'N', });
      }
      this.updateUrlWithNewFilter(this.jFilter);
    }

    this.cdr.detectChanges();
  }



  formatChanged(e) {

    this.mask = "";
    switch (e.value) {
      case "DD-MM-YYYY":
        this.mask = "00-00-0000";
        break;
      case "DD MON YYYY":
        this.mask = "00 AAA 0000";
        break;
      case "MM-YYYY":
        this.mask = "00-0000";
        break;
      case "YYYY":
        this.mask = "0000";
        break;
      case "MM - MM YYYY":
        this.mask = "00 - 00 0000";
        break;
      case "DD - DD MON YYYY":
        this.mask = "00 - 00 AAA 0000";
        break;
      case "DD - DD MM YYYY":
        this.mask = "00 - 00 00 0000";
        break;
      case "MON - MON YYYY":
        this.mask = "AAA - AAA 0000";
        break;
      case "YYYY - YYYY":
        this.mask = "0000 - 0000";
        break;
      default:
        this.mask = "";
        break;
    }
  }


  clearinput(menu) {
    if (this.headSearvice.isGlobalSearch) {

      this.updateUrlWithNewFilter(this.jFilter);
      // if (this.elasticSummary?.totalBDIDs)
      //   this.elasticSummary.totalBDIDs = 0
      this.cs.callFunction({ event: 'SEARCH_CLEAR', jFilter: this.jFilter, type: 'N' });
    }
  }

  clearsearch() {
    this.clearFilters()
    this.OnClear.emit(true);
    this.cs.callFunction("RESET_FILES");
    this.cs.callFunction({ event: 'CLEAR_SEARCH_ELASTIC', jFilter: this.jFilter });
    this.cs.callFunction({ type: 'SEARCH-BUNDLES-CLEAR' });
    if (this.headSearvice.isGlobalSearch) {
      this.updateUrlWithNewFilter(this.jFilter);
    }
    this.cdr.detectChanges()
    setTimeout(() => {
      this.issearched = false;
      this.cdr.detectChanges()
    }, 100);
  }


  clearsearch_old(menu) {
    // try {
    //   // this.
    // } catch (error) {

    // }

    // this.headSearvice.search_within = null;
    this.headSearvice.isGlobalSearch = false;
    this.titleS.setTitle('HearingHub');
    this.cf.searchdate = 'A'; this.cf.searchin = 'M';
    this.dateType = 'A';
    this.mainsearch = false


    this.jFilter = { cMatchCase: 'C', cSearch: '', cLocation: 'A', cWithin: this.cf.searchin, contentType: 'All', jFTypes: [], nCaseid: this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid } as advanceFiler;

    this.cs.callFunction({ event: 'SEARCH_FILES', jFilter: this.jFilter, type: 'N' });
    this.OnClear.emit(true);
    this.cs.callFunction("RESET_FILES");
    this.cs.callFunction({ event: 'CLEAR_SEARCH_ELASTIC', jFilter: this.jFilter });
    this.cdr.detectChanges()
    setTimeout(() => {
      this.issearched = false;
      this.cdr.detectChanges()
    }, 100);
  }

  menuopened() {
    setTimeout(() => {
      this.myInputElementRef.nativeElement.focus();
    }, 10);
  }

  menuClose() {
    this.cs.callFunction("SEARCH_CLOSE");
  }

  ///// ALPHA


  emitSearch() {
    // this.onSearch.emit(this.jFilter);
    this.cs.callFunction({ event: 'SEARCH_ELASTIC', jFilter: this.jFilter });
    this.issearched = true;
    this.getBundlesOfElasticSearch(this.jFilter)
    this.getSummaryOfElasticSearch(this.jFilter)
    this.cdr.detectChanges();
  }
  async getBundlesOfElasticSearch(jFilter: advanceFiler) {

    const isCaseSensitive = jFilter.cMatchCase == 'E';
    const isStartWith = jFilter.cMatchCase == 'S';
    const isWholeWord = jFilter.cMatchCase == 'E';

    this.cs.callFunction({ type: 'SEARCH-BUNDLES-CLEAR' });
    const bundleSearch = await this.advanceSearchService.searchBundle(
      jFilter.cSearch,
      this.headSearvice?.nCaseid,
      isCaseSensitive,
      isStartWith,
      isWholeWord,
      jFilter?.jIssues,
      jFilter?.jImpact,
      jFilter?.jRelevance,
      jFilter?.jMarkup,
      jFilter.cLocation == 'A' ? null : jFilter.nBundleid
    );

    this.cs.callFunction({ type: 'SEARCH-BUNDLES', searchedBundles: bundleSearch?.bundleIds || [] });
  }

  async getSummaryOfElasticSearch(jFilter: advanceFiler) {
    const isCaseSensitive = jFilter.cMatchCase == 'E';
    const isStartWith = jFilter.cMatchCase == 'S';
    const isWholeWord = jFilter.cMatchCase == 'E';
    this.elasticSummary = await this.advanceSearchService.searchSummary(
      jFilter.cSearch,
      this.headSearvice?.nCaseid,
      isCaseSensitive,
      isStartWith,
      isWholeWord,
      jFilter?.jIssues,
      jFilter?.jImpact,
      jFilter?.jRelevance,
      jFilter?.jMarkup,
      jFilter.cLocation == 'A' ? null : jFilter.nBundleid,
      this.headSearvice?.nSectionid,
      this.headSearvice?.cFoldertype
    );
    this.cs.callFunction({ event: 'SEARCH_SUMMARY', elasticSummary: this.elasticSummary });
    this.cdr.detectChanges();
    // async searchSummary(searchTerm: string, nCaseid: string, isCaseSensitive: boolean, isStartWith: boolean, isWholeWord: boolean, jIssues?: number[], jImpact?: number[], jRelevance?: number[], jMarkup?: string[]): Promise<searchedSummary> {
  }



  onsearchInput(e: any) {
    // if (this.isadvanced) {
    this.jFilter.cSearch = e;
    // this.jFilterChange.emit(this.jFilter);
    // }
  }


  onTermCondition(event: any) {
    this.jFilter.cMatchCase = event;



    if (this.issearched) {
      this.searchChange();
    }

    this.cdr.detectChanges();
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['jFilter'] && !changes['jFilter'].firstChange) {
      if (this.headSearvice.isGlobalSearch) {
        if (this.jFilter.nBundleid == null) {
          this.jFilter.cLocation = this.jFilter?.cLocation || 'A';
          this.checkFilter();
        }
      }
    } if (changes['currentfolder']) {
      if (this.headSearvice.isGlobalSearch && changes['currentfolder'].firstChange) { return; }
      this.jFilter.nBundleid = this.currentfolder?.nBundleid || null;
      this.jFilter.nBundleid = this.currentfolder?.nBundleid || this.jFilter?.nBundleid || null;
      this.jFilter.cBundlename = this.currentfolder?.cBundlename || 'Master Bundle';
      if (!changes['currentfolder'].firstChange && this.headSearvice.isGlobalSearch) {
        if (this.cf.searchin == 'I') {
          this.getSummaryOfElasticSearch(this.jFilter);
        }
      }
      this.cdr.detectChanges();
    }

  }

  checkFilter() {
    if (this.jFilter.cSearch) {
      // this.cf.contentType = this.jFilter.cMatchCase;
      this.cf.searchin = this.jFilter.cWithin;

      this.issearched = true;
      try {
        this.cf.searchName = this.jFilter?.cMatchCase;
        // this.cf.searchFilter[0].list.map(e=>e.select = false)
        // const data = this.cf.searchFilter[0].list.find(e => e.nValue == this.jFilter?.cMatchCase)
        // if (data)
        //   data.select = true;
      } catch (error) {

      }
      this.cdr.detectChanges();
    }
  }


  filterchange(ev) {
    console.log(ev);

  }

  ngOnDestroy(): void {
    this.clearsearch()
    try {
      if (this.broadCastSubscription)
        this.broadCastSubscription.unsubscribe();

      if (this.searchInputClearSubscription) {
        this.searchInputClearSubscription.unsubscribe();
      }
    } catch (error) {

    }
  }


  resetSearch() {
    this.jFilter = { cMatchCase: 'E', cSearch: '' } as advanceFiler;
    this.cdr.detectChanges()
  }

  changeTypes(e, list, isAll) {
    debugger;
    if (isAll) {
      this.cf.jFTypes = [];
      for (let x of list)
        x.select = false
    } else {
      this.cf.jFTypes = [];
      for (let x of list) {
        if (x.select) {
          for (let y of x.types)
            this.cf.jFTypes.push(y)
        }
      }
    }



    const selectedCount = list.filter(e => e.select).length;

    // Set checkalltype to true if all are selected OR none are selected
    this.checkalltype = (selectedCount === list.length) || (selectedCount === 0);

  }

  typechange(ev) {
    debugger;;
    if (ev.value == 'I') {
      this.checkalltype = false;
      this.cf.jFTypes = ["PDF"];
    } else {
      this.cf.jFTypes = [];
      this.checkalltype = true;
    }
    this.jFilter.cWithin = ev.value;
  }

  updateUrlWithNewFilter(newFilter: any) {
    if (this.headSearvice.isGlobalSearch) {

      const updatedData = {
        id: this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid,
        jFilter: newFilter
      };

      const encoded = btoa(JSON.stringify(updatedData));
      const currentBase = this.router.url.split('/').slice(0, -1).join('/');
      const newUrl = `${currentBase}/${encoded}`;

      this.location.replaceState(newUrl); // updates URL without reloading
    }
  }

  clearFilters() {
    this.cf.searchdate = 'A'; // this.cf.searchin = 'M';
    this.dateType = 'A';
    this.jFilter = {
      cMatchCase: 'C', cSearch: '', cLocation: 'A', cWithin: this.jFilter.cWithin, contentType: 'All', jFTypes: [],
      nCaseid: this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid, isGlobalSearch: this.headSearvice.isGlobalSearch
    } as advanceFiler;
    this.headSearvice.jFilter = this.jFilter
    this.cs.callFunction({ event: 'SEARCH_CLEAR', jFilter: this.jFilter, type: 'N' });
  }

}